        private static void RunBranchIntegrationTests(string directory)
        {
            var book=StudioFixture();var store=new DiaryStore(Path.Combine(directory,"anniversaries"));store.Save(book);var loaded=store.Load();Check(loaded.Studio.Anniversaries.Count==2&&loaded.Studio.Anniversaries[0].Name=="상몬 생일","Anniversaries round-trip with existing photos, studio metadata and version-nine backups");
            using(var input=new MemoryStream(Encoding.UTF8.GetBytes("{\"RoomTheme\":0,\"Furniture\":[],\"Pages\":[]}"))){var old=(StudioData)new DataContractJsonSerializer(typeof(StudioData)).ReadObject(input);StudioData.Validate(old);Check(old.Anniversaries!=null&&old.Anniversaries.Count==0,"Old studio backups initialize a missing anniversary list");}
            Check(DiaryBrowse.Month(book,new DateTime(2030,6,1)).Single(d=>d.Date==new DateTime(2030,6,29)).AnniversaryNames=="상몬 생일","Yearly birthdays recur on the same month and day");Check(DiaryBrowse.Month(book,new DateTime(2026,11,1)).Single(d=>d.Date==new DateTime(2026,11,14)).HasAnniversary&&!DiaryBrowse.Month(book,new DateTime(2027,11,1)).Single(d=>d.Date==new DateTime(2027,11,14)).HasAnniversary,"One-time anniversaries never repeat in another year");book.Studio.Anniversaries.Add(new Anniversary{Id="leap",Name="윤년 생일",Date="2024-02-29"});Check(DiaryBrowse.Month(book,new DateTime(2028,2,1)).Single(d=>d.Date==new DateTime(2028,2,29)).HasAnniversary&&!DiaryBrowse.Month(book,new DateTime(2027,2,1)).Single(d=>d.Date==new DateTime(2027,2,28)).HasAnniversary,"Leap-day birthdays appear only on February twenty-nine");
            var merged=StudioData.Merge(book.Studio,new StudioData());Check(merged.Anniversaries.Count==3,"An old import without anniversaries preserves the current list");var incoming=new StudioData();incoming.Anniversaries.Add(new Anniversary{Id="leap",Name="새 이름",Date="2024-02-29"});merged=StudioData.Merge(book.Studio,incoming);Check(merged.Anniversaries.Count==3&&merged.Anniversaries.Single(a=>a.Id=="leap").Name=="새 이름"&&book.Studio.Anniversaries.Single(a=>a.Id=="leap").Name=="윤년 생일","Anniversary import merges by id without mutating either source");
            foreach(var bad in new[]{new Anniversary{Id="bad",Name="잘못된\n이름",Date="2026-11-14"},new Anniversary{Id="bad",Name=new string('가',41),Date="2026-11-14"},new Anniversary{Id="bad",Name="날짜",Date="2026-02-29"}}){bool rejected=false;try{StudioData.Validate(new StudioData{Anniversaries=new List<Anniversary>{bad}});}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid anniversary names or dates are rejected before storage: "+bad.Name.Length);}
            bool invalid=false;try{StudioData.Validate(new StudioData{Anniversaries=Enumerable.Range(0,501).Select(i=>new Anniversary{Id="id"+i,Name="기념일",Date="2026-11-14"}).ToList()});}catch(InvalidDataException){invalid=true;}Check(invalid,"Anniversary lists are bounded at five hundred entries");
            var previous=book.Studio;byte[] disk=File.ReadAllBytes(store.FilePath);bool failed=false;try{Anniversaries.Commit(book,new[]{new Anniversary{Id="next",Name="저장 실패",Date="2026-11-14"}},()=>{throw new IOException("read only");});}catch(IOException){failed=true;}Check(failed&&ReferenceEquals(book.Studio,previous)&&disk.SequenceEqual(File.ReadAllBytes(store.FilePath)),"Failed anniversary saves roll memory back and leave the diary file unchanged");
            string legacy=Path.Combine(directory,"tetris-record.json"),scores=Path.Combine(directory,"migrated-scores","scores.json");File.WriteAllText(legacy,"{\"HighScore\":750}");byte[] original=File.ReadAllBytes(legacy);var records=new GameRecords(scores);records.Record("blocks",500);records.Record("bake",150);Check(records.ImportLegacyTetris(legacy)&&records.Best("blocks")==750&&records.Plays("blocks")==1&&records.Best("bake")==150&&original.SequenceEqual(File.ReadAllBytes(legacy)),"Legacy Tetris best imports into Sangmon blocks without inventing a play or touching the source");byte[] scoreBytes=File.ReadAllBytes(scores);Check(records.ImportLegacyTetris(legacy)&&scoreBytes.SequenceEqual(File.ReadAllBytes(scores)),"Repeated legacy import does not rewrite a record already imported");records.Record("blocks",900);Check(records.ImportLegacyTetris(legacy)&&records.Best("blocks")==900&&records.Plays("blocks")==2,"A lower old Tetris score never replaces the new game's best");var fresh=new GameRecords();Check(fresh.ImportLegacyTetris(legacy)&&fresh.Best("blocks")==750&&fresh.Plays("blocks")==0,"Importing a first legacy best does not count it as a newly completed round");File.WriteAllText(legacy,"broken");Check(!records.ImportLegacyTetris(legacy)&&records.Best("blocks")==900&&File.ReadAllText(legacy)=="broken"&&records.Record("fish",30),"A broken old score is preserved and does not prevent saving other games");File.WriteAllText(legacy,new string('x',1025));Check(!records.ImportLegacyTetris(legacy),"Oversized legacy score files are ignored safely");
        }
        public static void BranchIntegrationPreview(string directory)
        {
            Directory.CreateDirectory(directory);var book=StudioFixture();int saves=0;bool fail=false;
            using(var manager=new AnniversaryWindow(book,()=>{if(fail)throw new IOException("blocked");saves++;})){manager.Show();Application.DoEvents();manager.VerifyLayoutForTest();if(!manager.AddForTest("먼저 표시할 날",new DateTime(2020,1,1),true))throw new Exception("Anniversary add failed");string id=book.Studio.Anniversaries.Single(a=>a.Name=="먼저 표시할 날").Id;if(!manager.RemoveForTest(id)||book.Studio.Anniversaries.Any(a=>a.Id==id)||book.Studio.Anniversaries.Count!=2)throw new Exception("Sorted anniversary removal selected the wrong record");fail=true;var old=book.Studio;if(manager.AddForTest("실패한 기념일",new DateTime(2026,11,14),false)||!ReferenceEquals(book.Studio,old))throw new Exception("Native anniversary failure did not roll back");fail=false;using(var image=new Bitmap(manager.Width,manager.Height)){manager.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-integrated-anniversaries.png"));}manager.ClientSize=Design.Size(460,430);Application.DoEvents();manager.VerifyLayoutForTest();manager.Close();}if(saves!=2)throw new Exception("Anniversary actions did not save exactly once");
            using(var calendar=new MyDay.Windows.UI.MonthCalendar(book,new DateTime(2026,11,14),DateTime.MinValue,DateTime.MaxValue,delegate{})){calendar.Size=Design.Size(330,380);calendar.SetMonth(new DateTime(2026,11,1));var day=calendar.FindDay(new DateTime(2026,11,14));if(!day.Day.HasAnniversary||!day.AccessibleName.Contains("프로젝트 발표"))throw new Exception("Calendar anniversary accessibility missing");using(var image=new Bitmap(calendar.Width,calendar.Height)){calendar.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-integrated-calendar.png"));}}
            using(var browser=new JournalBrowser(book,new DateTime(2026,11,14),new DateTime(1900,1,1),new DateTime(9998,12,31),()=>{})){browser.Show();Application.DoEvents();using(var image=new Bitmap(browser.Width,browser.Height)){browser.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-integrated-browser.png"));}browser.Close();}
            string root=Path.Combine(directory,"menu-data");var store=new DiaryStore(root);store.Save(book);using(var diary=new DiaryWindow(store,book,true)){diary.StartOnDesktop();diary.OpenDiary();Application.DoEvents();var menu=diary.GamesMenuForTest();if(menu.Items.OfType<ToolStripMenuItem>().Count()!=9||!menu.Items.OfType<ToolStripMenuItem>().Any(item=>item.Text=="상몬 블록 쌓기")||!menu.Items.OfType<ToolStripMenuItem>().Any(item=>item.Text=="플레이룸 전체 보기"))throw new Exception("Compact menu omitted an existing game or playroom/fetch");menu.Show(diary,new Point(Design.P(30),Design.P(120)));Application.DoEvents();using(var image=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-integrated-games-menu.png"));}menu.Close();bool opened=false;diary.OpenBlockFromMenuForTest(form=>{if(!(form is BlockGameWindow))throw new Exception("Compact Tetris entry replaced the Sangmon design");opened=true;form.Close();});if(!opened)throw new Exception("The direct menu did not open a game");diary.ExitApp();}
            var records=new GameRecords();records.Record("blocks",2450);using(var game=new BlockGameWindow(records)){game.Show();Application.DoEvents();game.StartRound();game.Game.SetPieceForTest(BlockKind.T,0,3,4);for(int y=17;y<20;y++)for(int x=0;x<10;x++)if((x+y)%4!=0)game.Game.SetCellForTest(x,y,(x+y)%7+1);game.SavePreview(Path.Combine(directory,"windows-integrated-blocks-best.png"));game.Close();}if(records.Plays("blocks")!=1)throw new Exception("Opening and closing a game changed completed plays");
            Console.WriteLine("Native branch integration: anniversary add/sorted delete/save rollback, calendar marker/accessibility, browser, compact menu, original Sangmon block route and separate best card passed.");
        }
    }
